// Reconciliation engine — deterministic checks against quote/PO
try {
  const _ = $input.all();
  const trigger = $('Trigger').first().json;
  const invoiceId = trigger.invoice_id;
  const header = $('Read Invoice Header').first().json;
  const invoiceLines = $('Read Invoice Lines').all().map(i => i.json);
  const vendors = $('Read Vendors').all().map(i => i.json);
  const projects = $('Read Projects').all().map(i => i.json);
  const quotes = $('Read Quotes').all().map(i => i.json);
  const quoteLines = $('Read Quote Lines').all().map(i => i.json);
  const pos = $('Read POs').all().map(i => i.json);
  const poLines = $('Read PO Lines').all().map(i => i.json);
  const books = $('Read Books').all().map(i => i.json);
  const pendingAll = $('Read All Pending').all().map(i => i.json);

  const norm = (s) => String(s || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, ' ').trim();
  const fuzzy = (a, b) => {
    if (!a || !b) return false;
    const na = norm(a), nb = norm(b);
    if (!na || !nb) return false;
    return na === nb || na.includes(nb) || nb.includes(na);
  };
  const matchesAlias = (record, target) => {
    const fields = ['vendor_name', 'project_name', 'name'];
    for (const f of fields) {
      if (record[f] && fuzzy(record[f], target)) return true;
    }
    if (record.aliases) {
      const aliases = String(record.aliases).split(/[,;|]/).map(a => a.trim()).filter(Boolean);
      if (aliases.some(a => fuzzy(a, target))) return true;
    }
    return false;
  };

  const vendor = vendors.find(v => matchesAlias(v, header.vendor_name)) || null;
  const project = projects.find(p => matchesAlias(p, header.project_name)) || null;

  const matchingQuotes = quotes.filter(q =>
    fuzzy(q.vendor_name, header.vendor_name) && fuzzy(q.project_name, header.project_name)
  ).sort((a, b) => new Date(b.date || 0) - new Date(a.date || 0));
  const quote = matchingQuotes[0] || null;
  const matchedQuoteLines = quote ? quoteLines.filter(l => l.quote_id === quote.quote_id) : [];

  const matchingPOs = pos.filter(p =>
    fuzzy(p.vendor_name, header.vendor_name) && fuzzy(p.project_name, header.project_name)
  ).sort((a, b) => new Date(b.date || 0) - new Date(a.date || 0));
  const po = matchingPOs[0] || null;
  const matchedPOLines = po ? poLines.filter(l => l.po_id === po.po_id) : [];

  const flags = [];
  const invoiceTotal = parseFloat(header.total) || 0;
  let varianceAmount = 0;

  const refDoc = po || quote;
  const refLines = po ? matchedPOLines : matchedQuoteLines;
  const refLabel = po ? 'PO' : 'quote';

  if (!quote) {
    flags.push({ type: 'missing_quote', detail: `No matching quote found for vendor "${header.vendor_name}" on project "${header.project_name}"`, severity: 'high' });
  }

  if (refDoc) {
    const refTotal = parseFloat(refDoc.total) || 0;
    const tolerance = Math.max(50, refTotal * 0.02);
    varianceAmount = Number((invoiceTotal - refTotal).toFixed(2));
    if (Math.abs(varianceAmount) > tolerance) {
      flags.push({
        type: 'total_variance',
        detail: `Invoice total $${invoiceTotal.toFixed(2)} ${varianceAmount > 0 ? 'exceeds' : 'is below'} ${refLabel} total $${refTotal.toFixed(2)} by $${Math.abs(varianceAmount).toFixed(2)} (tolerance $${tolerance.toFixed(2)})`,
        severity: Math.abs(varianceAmount) > tolerance * 5 ? 'high' : 'medium'
      });
    }
  }

  if (refLines.length > 0) {
    for (const invLine of invoiceLines) {
      const matched = refLines.find(rl => fuzzy(rl.description, invLine.description));
      if (!matched) {
        flags.push({ type: 'unmatched_line', detail: `Invoice line "${invLine.description}" ($${(parseFloat(invLine.line_total)||0).toFixed(2)}) has no matching line on ${refLabel}`, severity: 'medium' });
      } else {
        const invAmt = parseFloat(invLine.line_total) || 0;
        const refAmt = parseFloat(matched.line_total) || 0;
        const lineTol = Math.max(10, refAmt * 0.02);
        if (Math.abs(invAmt - refAmt) > lineTol) {
          flags.push({ type: 'line_amount_variance', detail: `Line "${invLine.description}": invoice $${invAmt.toFixed(2)} vs ${refLabel} $${refAmt.toFixed(2)}`, severity: 'low' });
        }
      }
    }
  }

  const invDate = header.date ? new Date(header.date) : null;
  const today = new Date();
  if (invDate && !isNaN(invDate)) {
    if (invDate > today) {
      flags.push({ type: 'future_date', detail: `Invoice date ${header.date} is in the future`, severity: 'high' });
    }
    if (refDoc && refDoc.date) {
      const refDate = new Date(refDoc.date);
      if (!isNaN(refDate) && invDate < refDate) {
        flags.push({ type: 'date_before_quote', detail: `Invoice date ${header.date} predates ${refLabel} date ${refDoc.date}`, severity: 'medium' });
      }
    }
  }

  if (header.invoice_number) {
    const dupe = pendingAll.find(p =>
      p.invoice_id !== invoiceId &&
      p.invoice_number &&
      String(p.invoice_number).trim() === String(header.invoice_number).trim() &&
      fuzzy(p.vendor_name, header.vendor_name)
    );
    if (dupe) {
      flags.push({ type: 'duplicate_invoice', detail: `Invoice number ${header.invoice_number} already exists for vendor "${header.vendor_name}" (existing invoice_id ${dupe.invoice_id})`, severity: 'high' });
    }
  }

  const lineSum = invoiceLines.reduce((s, l) => s + (parseFloat(l.line_total) || 0), 0);
  const headerSubtotal = header.subtotal != null && header.subtotal !== '' ? parseFloat(header.subtotal) : null;
  const headerGst = header.gst != null && header.gst !== '' ? parseFloat(header.gst) : null;
  if (headerSubtotal != null && Math.abs(lineSum - headerSubtotal) > 1) {
    flags.push({ type: 'math_subtotal', detail: `Line items sum to $${lineSum.toFixed(2)} but header subtotal is $${headerSubtotal.toFixed(2)}`, severity: 'medium' });
  }
  if (headerSubtotal != null && headerGst != null) {
    const expectedGst = headerSubtotal * 0.05;
    if (Math.abs(headerGst - expectedGst) > 1) {
      flags.push({ type: 'math_gst', detail: `GST $${headerGst.toFixed(2)} is not 5% of subtotal $${headerSubtotal.toFixed(2)} (expected $${expectedGst.toFixed(2)})`, severity: 'low' });
    }
    if (Math.abs((headerSubtotal + headerGst) - invoiceTotal) > 1) {
      flags.push({ type: 'math_total', detail: `Subtotal $${headerSubtotal.toFixed(2)} + GST $${headerGst.toFixed(2)} does not equal total $${invoiceTotal.toFixed(2)}`, severity: 'medium' });
    }
  }

  let costCode = 'UNCATEGORIZED';
  if (vendor && vendor.default_cost_code) costCode = vendor.default_cost_code;
  else if (invoiceLines[0] && invoiceLines[0].cost_code) costCode = invoiceLines[0].cost_code;

  const isClean = flags.length === 0;
  const flagSummary = flags.length === 0 ? 'no flags' : flags.map((f, i) => `${i + 1}. [${f.severity}] ${f.type}: ${f.detail}`).join('\n');

  return [{
    json: {
      invoice_id: invoiceId,
      invoice_number: header.invoice_number || '',
      vendor_name: header.vendor_name || '',
      project_name: header.project_name || '',
      invoice_date: header.date || '',
      invoice_total: invoiceTotal,
      is_clean: isClean,
      flags,
      flags_json: JSON.stringify(flags),
      flag_summary: flagSummary,
      variance_amount: varianceAmount,
      matched_quote_id: quote ? quote.quote_id : '',
      matched_po_id: po ? po.po_id : '',
      quote_total: quote ? (parseFloat(quote.total) || 0) : 0,
      po_total: po ? (parseFloat(po.total) || 0) : 0,
      ref_label: refLabel,
      cost_code: costCode,
      today_iso: today.toISOString().slice(0, 10),
      today_iso_full: today.toISOString(),
      invoice_header: header,
      invoice_lines: invoiceLines,
      matched_quote: quote,
      matched_po: po,
      matched_quote_lines: matchedQuoteLines,
      matched_po_lines: matchedPOLines,
      vendor_record: vendor,
      project_record: project,
      vendor_email: (vendor && vendor.email) ? vendor.email : ''
    }
  }];
} catch (err) {
  return [{
    json: {
      invoice_id: $('Trigger').first().json.invoice_id,
      is_clean: false,
      flags: [{ type: 'reconciliation_error', detail: String(err && err.message || err), severity: 'high' }],
      flags_json: JSON.stringify([{ type: 'reconciliation_error', detail: String(err && err.message || err), severity: 'high' }]),
      flag_summary: `Reconciliation error: ${err && err.message || err}`,
      vendor_name: '', project_name: '', invoice_number: '', invoice_total: 0,
      matched_quote_id: '', matched_po_id: '', quote_total: 0, po_total: 0,
      ref_label: 'quote', variance_amount: 0, cost_code: 'UNCATEGORIZED',
      today_iso: new Date().toISOString().slice(0,10),
      vendor_email: '', invoice_lines: [], invoice_date: ''
    }
  }];
}

const r = $input.first().json;
const entry_id = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : ('entry-' + Date.now() + '-' + Math.random().toString(36).slice(2, 10));
return [{
  json: {
    entry_id,
    invoice_id: r.invoice_id,
    date_approved: r.today_iso,
    vendor_name: r.vendor_name,
    project_name: r.project_name,
    total: r.invoice_total,
    cost_code: r.cost_code,
    notes: 'Auto-approved by reconciliation'
  }
}];

const _ = $input.all();
const r = $('Reconcile').first().json;
return [{
  json: {
    timestamp: new Date().toISOString(),
    type: 'auto_approved',
    invoice_id: r.invoice_id,
    invoice_number: r.invoice_number,
    vendor_name: r.vendor_name,
    project_name: r.project_name,
    message: `Invoice ${r.invoice_number} from ${r.vendor_name} auto-approved. $${Number(r.invoice_total).toFixed(2)} added to Books.`
  }
}];

