const r = $('Reconcile').first().json;
const llmOut = $input.first().json || {};
let draft = '';
if (llmOut && typeof llmOut === 'object') {
  if (llmOut.message && llmOut.message.content) draft = llmOut.message.content;
  else if (llmOut.content) draft = llmOut.content;
  else if (llmOut.output) draft = String(llmOut.output);
  else if (llmOut.text) draft = llmOut.text;
  else draft = '';
}
if (!draft) {
  draft = `Hi ${r.vendor_name || 'team'},\n\nWe've received invoice ${r.invoice_number} for project ${r.project_name} and noticed a few items we'd like to confirm:\n\n${r.flag_summary}\n\nCould you take a quick look and let us know? Looking forward to your response.`;
}
return [{ json: Object.assign({}, r, { draft_response: draft }) }];

const _ = $input.all();
const r = $('Reconcile').first().json;
return [{
  json: {
    timestamp: new Date().toISOString(),
    type: 'review_needed',
    invoice_id: r.invoice_id,
    invoice_number: r.invoice_number,
    vendor_name: r.vendor_name,
    project_name: r.project_name,
    message: `Review needed for invoice ${r.invoice_number} from ${r.vendor_name}. ${r.flags.length} flag(s): ${r.flags.map(f => f.type).join(', ')}. Approve at: ${$execution.resumeFormUrl}`
  }
}];

const r = $('Reconcile').first().json;
const entry_id = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : ('entry-' + Date.now() + '-' + Math.random().toString(36).slice(2, 10));
const pmNotes = $('Wait for PM Review').first().json.pm_notes || '';
return [{
  json: {
    entry_id,
    invoice_id: r.invoice_id,
    date_approved: r.today_iso,
    vendor_name: r.vendor_name,
    project_name: r.project_name,
    total: r.invoice_total,
    cost_code: r.cost_code,
    notes: 'Human-approved after review' + (pmNotes ? ' — ' + pmNotes : '')
  }
}];

const _ = $input.all();
const r = $('Reconcile').first().json;
return [{
  json: {
    timestamp: new Date().toISOString(),
    type: 'human_approved',
    invoice_id: r.invoice_id,
    invoice_number: r.invoice_number,
    vendor_name: r.vendor_name,
    project_name: r.project_name,
    message: `Invoice ${r.invoice_number} from ${r.vendor_name} approved by PM after review. Email sent to vendor; $${Number(r.invoice_total).toFixed(2)} added to Books.`
  }
}];

const _ = $input.all();
const r = $('Reconcile').first().json;
const pmNotes = $('Wait for PM Review').first().json.pm_notes || '';
return [{
  json: {
    timestamp: new Date().toISOString(),
    type: 'disputed',
    invoice_id: r.invoice_id,
    invoice_number: r.invoice_number,
    vendor_name: r.vendor_name,
    project_name: r.project_name,
    message: `Invoice ${r.invoice_number} from ${r.vendor_name} marked disputed by PM.${pmNotes ? ' Notes: ' + pmNotes : ''} No email sent; not added to Books.`
  }
}];
